    return {"x": x}

_pair = provider(fields = ["x"], init = _uinit)
_plain = struct(p = provider(fields = ["x"]))

def _probe(ctx):
    lines = []
    if ctx.attr.which == "init":
        v = _pair[0](1)
    elif ctx.attr.which == "raw":
        v = _pair[1](x = 2)
    else:
        v = _plain.p(x = 3)
    lines.append("type=" + type(v))
    lines.append("x=" + repr(v.x))
    lines.append("repr(provider)=" + repr(_pair[0]))
    out = ctx.actions.declare_file(ctx.label.name + ".txt")
    ctx.actions.write(out, "\n".join(lines) + "\n")
    return [DefaultInfo(files = depset([out]))]

uprobe = rule(implementation = _probe, attrs = {"which": attr.string()})

